import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: ChatManager","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ChatManager"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/ChatManager"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/ChatManager"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/ChatManager.md","filePath":"api/@jsprismarine/prismarine/classes/ChatManager.md","lastUpdated":1794451102000}`),a={name:`api/@jsprismarine/prismarine/classes/ChatManager.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/prismarine</a> / ChatManager</p><h1 id="class-chatmanager" tabindex="-1">Class: ChatManager <a class="header-anchor" href="#class-chatmanager" aria-label="Permalink to “Class: ChatManager”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L104" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:104</a></p><p>Chat for the whole server: sending a message, and which players it reaches.</p><p>A message goes out as a <code>chat</code> event, and everything that shows chat listens for it: the console, the remote console, plugins and every player that has joined. A player joins the fan-out with <a href="#join">ChatManager.join</a> once its join completes and leaves it with <a href="#leave">ChatManager.leave</a>, both keyed by <code>keyOfPlayer</code>. The table is server-wide state, not a world&#39;s, so it changes when the call is made, inside a tick or between ticks.</p><p>Each recipient is its own <code>chat</code> listener, added when it joins. A listener that cancels the event therefore stops the players who joined after that listener was added, and not the ones who joined before it, as when each player subscribed itself.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ChatManager</strong>(<code>server</code>): <code>ChatManager</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L113" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:113</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="server" tabindex="-1">server <a class="header-anchor" href="#server" aria-label="Permalink to “server”">​</a></h5><p><a href="./../#chatbus"><code>ChatBus</code></a></p><p>The bus <code>chat</code> events go out on, which is the server&#39;s.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ChatManager</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="hasjoined" tabindex="-1">hasJoined() <a class="header-anchor" href="#hasjoined" aria-label="Permalink to “hasJoined()”">​</a></h3><blockquote><p><strong>hasJoined</strong>(<code>key</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L159" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:159</a></p><p>Whether a player is in the fan-out under a key.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="key" tabindex="-1">key <a class="header-anchor" href="#key" aria-label="Permalink to “key”">​</a></h5><p><code>string</code></p><p>The player&#39;s key; see <code>keyOfPlayer</code>.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="join" tabindex="-1">join() <a class="header-anchor" href="#join" aria-label="Permalink to “join()”">​</a></h3><blockquote><p><strong>join</strong>(<code>recipient</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L130" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:130</a></p><p>Adds a player to the fan-out. A player already joined under the same key is replaced.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="recipient" tabindex="-1">recipient <a class="header-anchor" href="#recipient" aria-label="Permalink to “recipient”">​</a></h5><p><a href="./../#chatrecipient"><code>ChatRecipient</code></a></p><p>The connected player.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="leave" tabindex="-1">leave() <a class="header-anchor" href="#leave" aria-label="Permalink to “leave()”">​</a></h3><blockquote><p><strong>leave</strong>(<code>recipient</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L148" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:148</a></p><p>Takes a player out of the fan-out. Does nothing when another player holds the key by now, so a replaced login leaving late does not take its successor&#39;s chat with it.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="recipient-1" tabindex="-1">recipient <a class="header-anchor" href="#recipient-1" aria-label="Permalink to “recipient”">​</a></h5><p><a href="./../#chatrecipient"><code>ChatRecipient</code></a></p><p>The recipient <a href="#join">ChatManager.join</a> was given.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>chat</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/9b55d0b3ceeeace88c23ed76a207eae4752924cf/packages/prismarine/src/chat/ChatManager.ts#L121" target="_blank" rel="noreferrer">prismarine/src/chat/ChatManager.ts:121</a></p><p>Sends a message to the console, the plugins and every player its channel reaches.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chat" tabindex="-1">chat <a class="header-anchor" href="#chat" aria-label="Permalink to “chat”">​</a></h5><p><a href="./Chat.html"><code>Chat</code></a></p><p>The message.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>`,60)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};